/**
 * Test support (no production code): small PartDesign parts made for the
 * patterns, Mirrored, MultiTransform and Hole slice (ADR-0144 S7). The parts
 * are ours: built with FreeCAD 1.1.4 by the script beside this package
 * (`packages/fcstd/scripts/make-pattern-fixtures.py`), so each stored shape,
 * each property as FreeCAD writes it and the `EdgeN` / `FaceN` numbering are
 * FreeCAD's own. Generated from the script's output: the stored B-rep texts
 * (each distinct text once, `BREP`), each object's properties as its own XML
 * holds them (each distinct list once, `PROPS`; labels, shapes, placements and
 * display settings left out), FreeCAD's measures of each stored shape and its
 * description of each element a property names (`subInfo`). Sketches are
 * their geometry and stored placement (position, then the rotation as a
 * quaternion x, y, z, w). In the B-rep texts each run of spaces is one space
 * (OCCT reads them by words; it keeps the fixtures small), nothing else changed.
 */
/* biome-ignore-all lint: generated data */

/** A property: its name, FreeCAD type and value (see `patternObject`). */
export type FixtureProp = readonly [string, string, unknown];
export interface PatternFixtureObject {
  readonly object: string;
  readonly type?: string;
  /** Index into `PROPS`. */
  readonly props?: number;
  /** Index into `BREP`. */
  readonly stored?: number;
  readonly measure?: {
    readonly volume: number;
    readonly area: number;
    readonly box: readonly number[];
    readonly centre: readonly number[];
  };
  readonly subInfo?: Readonly<Record<string, readonly Record<string, unknown>[]>>;
  readonly sketch?: {
    /** Position, then the rotation as a quaternion (x, y, z, w). */
    readonly at: readonly number[];
    readonly geometry: readonly (readonly (string | number)[])[];
  };
}
export interface PatternFixtureCase {
  readonly note: string;
  readonly tip: string;
  readonly group: readonly string[];
  readonly objects: readonly PatternFixtureObject[];
}

